<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, ref } from 'vue';
import KlineChart from '../components/KlineChart.vue';
import type { KlineBar } from '../types/market';
type Scalar = number | string | null;
interface Contract { instrument_id: string; code: string; name: string; commodity_code: string; contract_kind: string; latest_date: string | null; price_unit: string | null; tick_size: Scalar; trade_unit: string | null; exchange: string; }
interface Daily { bar_date: string; open: Scalar; high: Scalar; low: Scalar; close: Scalar; volume: Scalar; settlement: Scalar; open_interest: Scalar; channel: string; }
interface Mapping { trade_date: string; underlying_code: string; method_code: string; source: string; }
interface Receipt { report_date: string; amount: Scalar; unit: string | null; source: string; }
interface Coverage { product_code: string; dataset: string; target_date: string; latest_date: string | null; status: string; written_count: number; expected_count: number | null; gaps: unknown[]; }
interface Detail { bars: Daily[]; mapping: Mapping[]; receipts: Receipt[]; }
const NAMES: Record<string,string> = { AU:'沪金',CU:'沪铜',AL:'沪铝',SC:'原油',LH:'生猪',RB:'螺纹钢',I:'铁矿石',J:'焦炭',MA:'甲醇',TA:'PTA',UR:'尿素',PP:'聚丙烯',LC:'碳酸锂',NI:'沪镍',ZN:'沪锌' };
const DATASETS: Record<string,string> = { catalog:'合约目录',daily:'真实合约日线',continuous:'主力连续',warehouse_warrant:'仓单',inventory:'总库存',settlement:'结算价' };
const STATUS: Record<string,string> = {ok:'已更新',partial:'部分缺失',missing:'缺失',stale:'未更新',unsupported:'来源不支持',upstream_failed:'来源失败'};
const TABS = [{key:'daily',label:'日线明细'},{key:'mapping',label:'换月映射'},{key:'receipts',label:'仓单'},{key:'coverage',label:'数据覆盖'}];
const contracts=ref<Contract[]>([]), coverage=ref<Coverage[]>([]), detail=ref<Detail|null>(null);
const product=ref(''),code=ref(''),search=ref(''),tab=ref('daily'),range=ref(100),loading=ref(true),detailLoading=ref(false),error=ref(''),detailError=ref('');
let controller:AbortController|null=null, requestId=0;
const products=computed(()=>[...new Set(contracts.value.map(x=>x.commodity_code))].sort((a,b)=>a.localeCompare(b)));
const visibleProducts=computed(()=>products.value.filter(p=>(p+' '+(NAMES[p]??'')).toLowerCase().includes(search.value.trim().toLowerCase())));
const selected=computed(()=>contracts.value.find(c=>c.code===code.value));
function type(c:Contract){return c.contract_kind==='main_continuous'?'供应商主连':c.contract_kind==='listed'&&/^[A-Z]+\d{3,4}\./.test(c.code)&&!/(8888|7777|9999)\./.test(c.code)?'真实合约':'其他系列';}
const grouped=computed(()=>['供应商主连','真实合约','其他系列'].map(label=>({label,items:contracts.value.filter(c=>c.commodity_code===product.value&&type(c)===label)})).filter(g=>g.items.length));
const daily=computed(()=>[...(detail.value?.bars??[])].sort((a,b)=>b.bar_date.localeCompare(a.bar_date)));
const latest=computed(()=>daily.value[0]);
const change=computed(()=>{const a=Number(latest.value?.close),b=Number(daily.value[1]?.close);return a>0&&b>0?(a/b-1)*100:null;});
const productCoverage=computed(()=>coverage.value.filter(c=>c.product_code===product.value));
const target=computed(()=>productCoverage.value.map(c=>date(c.target_date)).sort().at(-1)??'');
const hasGaps=computed(()=>productCoverage.value.some(c=>c.status!=='ok'));
const digits=computed(()=>{const tick=selected.value?.tick_size;return tick!=null?Math.min(6,(String(tick).replace(/0+$/,'').split('.')[1]??'').length):3;});
const priceUnit=computed(()=>selected.value?.price_unit??'单位未披露');
// 当前目录未给成交量单位；不能把交易单位（吨/手）冒充成交量单位。
const chartBars=computed<KlineBar[]>(()=>daily.value.slice(0,range.value).filter(b=>[b.open,b.high,b.low,b.close].every(v=>v!==null&&Number.isFinite(Number(v))&&Number(v)>0)).reverse().map(b=>({date:date(b.bar_date),open:Number(b.open),high:Number(b.high),low:Number(b.low),close:Number(b.close),...(b.volume==null?{}:{volume:Number(b.volume)})})));
function date(v:string|null|undefined){return v?v.slice(0,10):'—';}
function fmt(v:Scalar|undefined,d=2){return v==null||!Number.isFinite(Number(v))?'缺失':Number(v).toLocaleString('zh-CN',{maximumFractionDigits:d});}
function gapText(g:unknown):string {if(typeof g==='string')return g;if(g&&typeof g==='object'){const r=g as Record<string,unknown>;return [r.code,r.reason??r.kind,r.stage?`阶段 ${r.stage}`:null,r.business_code?`业务码 ${r.business_code}`:null].filter(Boolean).join(' · ');}return '来源未提供说明';}
async function load(){loading.value=true;error.value='';try{const r=await fetch('/api/futures');if(!r.ok)throw Error('读取期货目录失败');const j=await r.json();contracts.value=j.contracts??[];coverage.value=j.coverage??[];let saved:{product?:string;code?:string}={};try{saved=JSON.parse(localStorage.getItem('futures-selection')??'{}');}catch{}product.value=products.value.includes(saved.product??'')?saved.product!:(products.value.includes('AU')?'AU':products.value[0]??'');chooseProduct(product.value,saved.code);}catch{error.value='读取期货目录失败，请检查本机服务后重读。';}finally{loading.value=false;}}
function chooseProduct(p:string,preferred?:string){product.value=p;const rows=contracts.value.filter(c=>c.commodity_code===p);const restored=rows.find(c=>c.code===preferred);const main=rows.find(c=>c.contract_kind==='main_continuous');const listed=rows.filter(c=>type(c)==='真实合约'&&c.latest_date).sort((a,b)=>(b.latest_date??'').localeCompare(a.latest_date??'')||a.code.localeCompare(b.code));code.value=(restored??main??listed[0]??rows[0])?.code??'';detail.value=null;if(code.value)void select();else{controller?.abort();requestId++;detailLoading.value=false;}}
async function select(){controller?.abort();controller=new AbortController();const current=++requestId;detail.value=null;detailError.value='';detailLoading.value=true;try{localStorage.setItem('futures-selection',JSON.stringify({product:product.value,code:code.value}));}catch{}try{const r=await fetch('/api/futures/'+encodeURIComponent(code.value)+'?limit=100',{signal:controller.signal});if(!r.ok)throw Error('detail');const j=await r.json();if(current===requestId)detail.value=j;}catch(e){if(current===requestId&&(e as Error).name!=='AbortError')detailError.value='读取当前系列失败，请重读；未触发外部取数。';}finally{if(current===requestId)detailLoading.value=false;}}
function tabKey(event:KeyboardEvent,index:number){if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?TABS.length-1:(index+(event.key==='ArrowRight'?1:-1)+TABS.length)%TABS.length;tab.value=TABS[next]!.key;document.getElementById('futures-tab-'+tab.value)?.focus();}
onMounted(load);onBeforeUnmount(()=>controller?.abort());
</script>
<template>
<section class="futures-page">
 <header class="page-heading"><div><h1>期货行情</h1></div><button class="quiet-button" @click="tab='coverage'">查看同步覆盖 <span aria-hidden="true">↗</span></button></header>
 <div v-if="error" class="empty-state" role="alert"><h2>目录暂不可用</h2><p>{{error}}</p><button @click="load">重新读取</button></div>
 <div v-else-if="loading" class="empty-state" role="status">正在读取已存期货目录…</div>
 <div v-else-if="!products.length" class="empty-state">暂无已存期货目录。本页不会自动取数或创建合约。</div>
 <div v-else class="workspace">
  <aside class="product-nav"><label class="search-label" for="futures-search">品种目录 <span>{{products.length}}</span></label><input id="futures-search" v-model="search" placeholder="搜索名称或代码" type="search" /><nav aria-label="期货品种"><button v-for="p in visibleProducts" :key="p" :class="['product-button',{active:product===p}]" :aria-pressed="product===p" @click="chooseProduct(p)"><span><strong>{{NAMES[p]??p}}</strong><small>{{contracts.find(c=>c.commodity_code===p)?.exchange??'交易所未披露'}}</small></span><span class="product-code">{{p}}<i aria-hidden="true">›</i></span></button><p v-if="!visibleProducts.length" class="muted">没有匹配品种</p></nav></aside>
  <div class="detail-area">
   <section class="quote-panel"><div class="quote-heading"><div><h2>{{NAMES[product]??product}} <span class="code-label">{{product}}</span></h2><p class="muted">{{selected?.exchange}} <span class="type-badge">{{selected?type(selected):'无系列'}}</span></p></div><label class="contract-select">当前系列<select v-model="code" @change="select"><optgroup v-for="g in grouped" :key="g.label" :label="g.label"><option v-for="c in g.items" :key="c.code" :value="c.code">{{c.name}} · {{c.code}}</option></optgroup></select></label></div>
   <div class="metrics" :aria-busy="detailLoading"><div><span>收盘价</span><strong>{{detailLoading?'—':fmt(latest?.close,digits)}}</strong><small>{{priceUnit}}</small></div><div><span>较上一条日线</span><strong :class="change==null?'':change>=0?'up':'down'">{{detailLoading||change==null?'—':`${change>=0?'+':''}${change.toFixed(2)}%`}}</strong><small>非实时涨跌</small></div><div class="secondary-metric"><span>结算价</span><strong>{{detailLoading?'—':fmt(latest?.settlement,digits)}}</strong><small>不以收盘替代</small></div><div class="secondary-metric"><span>持仓量</span><strong>{{detailLoading?'—':fmt(latest?.open_interest,0)}}</strong><small>单位未披露</small></div></div>
   <div class="data-caption"><span>{{code}} · 行情截至 {{date(latest?.bar_date)}} · {{latest?.channel??'来源待读取'}}</span><span v-if="target">覆盖目标 {{target}}</span></div>
   <div v-if="!detailLoading&&hasGaps" class="notice"><span>{{latest&&target>date(latest.bar_date)?'当前行情滞后，部分字段缺失。':'部分字段缺失或来源不支持。'}}</span><button @click="tab='coverage'">查看原因 →</button></div>
   <div class="chart-heading"><h3>日 K 线 <small>{{priceUnit}}</small></h3><div class="range-buttons" aria-label="显示日线条数"><button v-for="n in [30,60,100]" :key="n" :class="{active:range===n}" :aria-pressed="range===n" @click="range=n">{{n}}日</button></div></div>
   <div v-if="detailLoading" class="chart-state" role="status">正在读取 {{code}} 行情…</div><div v-else-if="detailError" class="chart-state" role="alert"><p>{{detailError}}</p><button @click="select">重读当前系列</button></div><template v-else-if="chartBars.length"><KlineChart :bars="chartBars" :title="code" :height="360" :price-unit="priceUnit" volume-unit="单位未披露" :price-digits="digits" :ma-visible="{ma5:false,ma10:false,ma20:false,ma60:false}"/><p class="chart-footnote">实际 {{chartBars.length}} 条 · {{chartBars[0]?.date}} — {{chartBars.at(-1)?.date}} · 成交量单位未披露；主连换月跳空不等于合约收益。</p></template><div v-else class="chart-state"><h3>当前系列暂无已存日线</h3><p>可以手动切换其他合约；不自动换约，也不显示演示行情。</p></div>
   </section>
   <section class="data-panel"><div class="tabs" role="tablist" aria-label="期货数据明细"><button v-for="(t,i) in TABS" :id="'futures-tab-'+t.key" :key="t.key" role="tab" :aria-selected="tab===t.key" :tabindex="tab===t.key?0:-1" :class="{active:tab===t.key}" @keydown="tabKey($event,i)" @click="tab=t.key">{{t.label}}<span v-if="t.key==='coverage'&&hasGaps" class="status-dot" /></button></div>
   <div role="tabpanel" :aria-labelledby="'futures-tab-'+tab" class="tab-content">
    <div v-if="tab==='daily'" class="table-scroll"><table v-if="daily.length"><thead><tr><th>交易日</th><th>开盘</th><th>最高</th><th>最低</th><th>收盘</th><th>成交量</th><th>结算</th><th>持仓量</th><th>来源</th></tr></thead><tbody><tr v-for="b in daily" :key="b.bar_date"><td>{{date(b.bar_date)}}</td><td>{{fmt(b.open,digits)}}</td><td>{{fmt(b.high,digits)}}</td><td>{{fmt(b.low,digits)}}</td><td>{{fmt(b.close,digits)}}</td><td>{{fmt(b.volume,0)}}</td><td>{{fmt(b.settlement,digits)}}</td><td>{{fmt(b.open_interest,0)}}</td><td>{{b.channel}}</td></tr></tbody></table><p v-else class="tab-empty">暂无已存日线明细</p></div>
    <template v-if="tab==='mapping'"><p class="muted">供应商换月规则未披露；仅展示已存映射，不外推历史成分。</p><div class="table-scroll" v-if="detail?.mapping.length"><table><thead><tr><th>交易日</th><th>实际合约</th><th>方法</th><th>来源</th></tr></thead><tbody><tr v-for="m in detail.mapping" :key="m.trade_date+m.method_code"><td>{{date(m.trade_date)}}</td><td>{{m.underlying_code}}</td><td>{{m.method_code}}</td><td>{{m.source}}</td></tr></tbody></table></div><p v-else class="tab-empty">{{selected&&type(selected)==='真实合约'?'真实合约无换月映射':'当前系列无已存换月映射'}}</p></template>
    <template v-if="tab==='receipts'"><p class="muted">仓单不等于总库存。数量与单位按来源原样展示，未知单位不换算。</p><div v-if="detail?.receipts.length" class="table-scroll"><table><thead><tr><th>报告日</th><th>数量</th><th>原单位</th><th>来源</th></tr></thead><tbody><tr v-for="r in detail.receipts" :key="r.report_date"><td>{{date(r.report_date)}}</td><td>{{fmt(r.amount,3)}}</td><td>{{r.unit??'单位未披露'}}</td><td>{{r.source}}</td></tr></tbody></table></div><p v-else class="tab-empty">当前系列无已存仓单记录，不代表仓单为零。</p></template>
    <div v-if="tab==='coverage'" class="table-scroll"><table v-if="productCoverage.length" class="coverage-table"><thead><tr><th>数据类型</th><th>状态</th><th>目标日 / 最新日</th><th>写入 / 应有</th><th>缺口说明</th></tr></thead><tbody><tr v-for="r in productCoverage" :key="r.dataset"><td>{{DATASETS[r.dataset]??r.dataset}}</td><td><span :class="['status-badge',r.status==='ok'?'ready':'warning']">{{STATUS[r.status]??r.status}}</span></td><td>{{date(r.target_date)}}<small>{{date(r.latest_date)}}</small></td><td>{{r.written_count}} / {{r.expected_count??'未知'}}</td><td><details v-if="r.gaps?.length"><summary>{{r.gaps.length}} 项说明</summary><ul><li v-for="(g,i) in r.gaps" :key="i">{{gapText(g)}}</li></ul></details><span v-else class="muted">无已记录缺口</span></td></tr></tbody></table><p v-else class="tab-empty">当前品种尚无同步覆盖记录</p></div>
   </div></section>
   <p class="disclaimer">只读研究视图 · 无交易或补数操作 · 缺失不等于零，历史走势不构成入场建议</p>
  </div>
 </div>
</section>
</template>
<style scoped>
.futures-page{container-type:inline-size;padding:24px;max-width:1600px;margin:auto;min-width:0;color:var(--ink)}.page-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:24px}.eyebrow{font-size:10px;letter-spacing:2px;color:var(--ink-faint);margin:0 0 7px}h1{font-size:26px;margin:0 0 8px;font-weight:650;letter-spacing:-.6px}.subtitle,.muted{color:var(--ink-faint);font-size:12px}.subtitle{margin:0}.workspace{display:grid;grid-template-columns:200px minmax(0,1fr);gap:20px;align-items:start}.product-nav,.quote-panel,.data-panel{background:var(--card);border:1px solid var(--line);border-radius:12px}.product-nav{padding:14px 10px;position:sticky;top:16px}.search-label{display:flex;justify-content:space-between;padding:2px 6px 12px;font-size:12px;font-weight:600}.search-label span{color:var(--ink-faint)}input,select{font:inherit;color:var(--ink);background:var(--card);border:1px solid var(--line);border-radius:7px;min-height:36px;max-width:100%}input{width:100%;box-sizing:border-box;padding:8px 10px;font-size:12px;margin-bottom:12px}button{font:inherit;cursor:pointer;color:inherit}button:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.product-nav nav{max-height:650px;overflow:auto}.product-button{display:flex;align-items:center;justify-content:space-between;width:100%;padding:12px 10px;border:0;border-radius:7px;background:transparent;text-align:left;margin:2px 0}.product-button:hover{background:var(--bg)}.product-button.active{background:var(--accent-soft,var(--bg));box-shadow:inset 3px 0 var(--accent)}.product-button strong{font-size:13px;font-weight:600}.product-button small{display:block;font-size:10px;color:var(--ink-faint);margin-top:4px}.product-code{font-family:monospace;font-size:11px;color:var(--ink-faint);display:flex;gap:12px}.product-code i{font-style:normal}.detail-area{min-width:0}.quote-panel{padding:22px}.quote-heading{display:flex;align-items:center;justify-content:space-between;gap:16px}h2{font-size:22px;margin:0 0 8px}.code-label{font:12px monospace;color:var(--ink-faint);margin-left:8px}.quote-heading p{margin:0}.type-badge{font-size:10px;padding:3px 7px;border:1px solid var(--line);border-radius:4px;margin-left:8px}.contract-select{display:grid;gap:5px;font-size:10px;color:var(--ink-faint);max-width:55%}.contract-select select{padding:7px 9px;font-size:12px;min-width:230px}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));padding:25px 0 20px;gap:16px}.metrics span,.metrics small{display:block;color:var(--ink-faint);font-size:11px}.metrics strong{display:block;font-size:25px;font-weight:600;letter-spacing:-.6px;font-variant-numeric:tabular-nums;margin:7px 0}.metrics small{font-size:10px}.up{color:var(--up)}.down{color:var(--down)}.data-caption{display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap;font-size:11px;color:var(--ink-faint);padding-bottom:14px;border-bottom:1px solid var(--line)}.notice{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:11px;margin-top:14px;padding:10px 12px;background:var(--bg);border-left:2px solid var(--warning,#ba914f);border-radius:4px}.notice button{border:0;white-space:nowrap;background:transparent;color:var(--accent);font-size:11px}.chart-heading{display:flex;align-items:center;justify-content:space-between;margin:20px 0 10px}.chart-heading h3{font-size:13px;margin:0}.chart-heading small{font-size:10px;color:var(--ink-faint);font-weight:400;margin-left:8px}.range-buttons{display:flex;gap:3px;padding:3px;border:1px solid var(--line);border-radius:6px}.range-buttons button{padding:4px 9px;border:0;border-radius:4px;font-size:11px;background:transparent;color:var(--ink-faint)}.range-buttons button.active{background:var(--bg);color:var(--ink)}.chart-footnote{font-size:10px;color:var(--ink-faint);margin:8px 0 0;line-height:1.7}.chart-state{min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;color:var(--ink-faint);font-size:12px;text-align:center;gap:8px}.chart-state h3{font-size:15px;color:var(--ink)}.data-panel{margin-top:18px;overflow:hidden}.tabs{display:flex;border-bottom:1px solid var(--line);padding:0 16px;overflow:auto}.tabs button{display:flex;gap:7px;align-items:center;border:0;border-bottom:2px solid transparent;background:transparent;white-space:nowrap;padding:16px 12px;font-size:12px;color:var(--ink-faint)}.tabs button.active{color:var(--ink);border-bottom-color:var(--accent)}.status-dot{height:5px;width:5px;border-radius:50%;background:var(--warning,#ba914f)}.tab-content{padding:0 16px 12px;min-height:120px}.tab-content>.muted{padding-top:10px}.table-scroll{overflow:auto;max-height:380px}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:11px;font-variant-numeric:tabular-nums}th,td{text-align:right;padding:12px 10px;border-bottom:1px solid var(--line)}th{position:sticky;top:0;background:var(--card);font-size:10px;color:var(--ink-faint);font-weight:500}th:first-child,td:first-child{text-align:left}td:last-child{color:var(--ink-faint)}.coverage-table td:last-child{text-align:left;max-width:320px;white-space:normal}.coverage-table small{display:block;color:var(--ink-faint);margin-top:4px}.status-badge{font-size:10px;padding:3px 6px;border-radius:4px;border:1px solid var(--line)}.ready{color:var(--ink-faint)}.warning{color:var(--warning,#ba914f)}details summary{cursor:pointer;color:var(--accent)}details ul{padding-left:16px;line-height:1.8;min-width:160px}.tab-empty{padding:35px 12px;text-align:center;font-size:12px;color:var(--ink-faint)}.quiet-button,.empty-state button,.chart-state button{border:1px solid var(--line);border-radius:6px;padding:9px 12px;background:var(--card);font-size:11px}.disclaimer{font-size:10px;color:var(--ink-faint);margin:15px 2px}.empty-state{padding:70px 20px;text-align:center;border:1px solid var(--line);border-radius:12px;background:var(--card)}
